def changed_paths(before, after):
    paths = set()

    def recurse(b, a, prefix):
        for key in set(b.keys()) | set(a.keys()):
            path = f"{prefix}.{key}" if prefix else key
            if key in b and key in a:
                bv, av = b[key], a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    recurse(bv, av, path)
                elif bv != av:
                    paths.add(path)
            else:
                paths.add(path)

    recurse(before, after, "")
    return sorted(paths)
